pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance as Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _test(uint256 amount1, uint256 amount2) internal {
        amount1 = bound(amount1, 0, 1000000000000000000000000000000);
        amount2 = bound(amount2, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(amount1 > 0 && amount2 > 0);
        vm.assume(address(this).balance >= amount1 + amount2);
        try c.addToBalance{value: amount1}() {} catch { return; }
        try c.addToBalance{value: amount2}() {} catch { return; }
        assertTrue(c.getBalance(address(this)) == amount1 + amount2);
    }

    function testFuzz_test(uint256 amount1, uint256 amount2) public {
        _test(amount1, amount2);
    }

    receive() external payable {}
}

